def seed_staff_read_state(apps, schema_editor):
    """A patient message staff answered or opened counts as read; trailing unopened ones stay unread."""
    PatientMessage = apps.get_model('care', 'PatientMessage')
    MessageThread = apps.get_model('care', 'MessageThread')
    for thread in MessageThread.objects.select_related('patient').iterator():
        patient_user = thread.patient.user_id
        if patient_user is None:
            continue
        messages = list(PatientMessage.objects.filter(thread=thread).order_by('created_at', 'pk')
                        .values('pk', 'sender_id', 'created_at'))
        last_staff_reply = None
        answered = []
        for message in reversed(messages):
            if message['sender_id'] != patient_user:
                last_staff_reply = message  # the nearest staff reply after the messages before it
            elif last_staff_reply is not None:
                answered.append((message['pk'], last_staff_reply))
        for pk, reply in answered:
            PatientMessage.objects.filter(pk=pk).update(staff_read_at=reply['created_at'], staff_read_by_id=reply['sender_id'])
    # Until now read_at on a patient's message meant "seen by staff", set when staff opened the conversation.
    PatientMessage.objects.filter(
        staff_read_at__isnull=True, read_at__isnull=False, sender_id=F('thread__patient__user_id'),
    ).update(staff_read_at=F('read_at'))


